-- Catálogo de materiais COD_MAT (Documento Mestre: materiais identificados por COD_MAT).
-- COD_MAT é o código do MATERIAL da biblioteca do SolidWorks (ex.: IN-001 = AISI 304), usado nas propriedades
-- das peças. Carga inicial: 124 materiais da biblioteca "Materiais_Fabriaco(2).sldmat" (lista que estava no
-- material de referência; o Gabriel deve confirmar se é a versão atual).

create table public.catalogo_materiais (
  cod_mat text primary key check (cod_mat ~ '^[A-Z]{2}-[0-9]{3}$'),
  nome text not null,
  nome_completo text not null default '',
  nome_solidworks text not null default '',
  categoria text not null default '',
  densidade numeric(10,3),          -- kg/dm³ (a preencher)
  ativo boolean not null default true,
  atualizado_em timestamptz not null default now()
);


alter table public.projeto_pecas add column cod_mat text references public.catalogo_materiais(cod_mat);

create trigger catalogo_materiais_atualizado before update on public.catalogo_materiais for each row execute function tocar_atualizado_em();
create trigger catalogo_materiais_auditoria after insert or update or delete on public.catalogo_materiais for each row execute function registrar_auditoria();

alter table public.catalogo_materiais enable row level security;
create policy catalogo_materiais_ler on public.catalogo_materiais for select to authenticated using (true);
create policy catalogo_materiais_admin on public.catalogo_materiais for all to authenticated using (tem_permissao('admin','editar')) with check (tem_permissao('admin','editar'));
grant select, insert, update, delete on public.catalogo_materiais to authenticated;
